$css = [System.IO.File]::ReadAllText("scratch\style_backup.css", [System.Text.Encoding]::UTF8)

$gridSystem = @'
:root{--bs-gutter-x:1.5rem;--bs-gutter-y:0}.row{display:flex;flex-wrap:wrap;margin-top:calc(-1 * var(--bs-gutter-y));margin-right:calc(-0.5 * var(--bs-gutter-x));margin-left:calc(-0.5 * var(--bs-gutter-x))}.row>*{box-sizing:border-box;flex-shrink:0;width:100%;max-width:100%;padding-right:calc(var(--bs-gutter-x) * 0.5);padding-left:calc(var(--bs-gutter-x) * 0.5);margin-top:var(--bs-gutter-y)}.g-3{--bs-gutter-x:1rem;--bs-gutter-y:1rem}.g-4{--bs-gutter-x:1.5rem;--bs-gutter-y:1.5rem}.g-5{--bs-gutter-x:3rem;--bs-gutter-y:3rem}@media (min-width:992px){.g-lg-5{--bs-gutter-x:3rem;--bs-gutter-y:3rem}}.col-auto{flex:0 0 auto;width:auto}.col-6{flex:0 0 auto;width:50%}.col-12{flex:0 0 auto;width:100%}@media (min-width:576px){.col-sm-6{flex:0 0 auto;width:50%}}@media (min-width:768px){.col-md-4{flex:0 0 auto;width:33.33333333%}.col-md-6{flex:0 0 auto;width:50%}}@media (min-width:992px){.col-lg-2{flex:0 0 auto;width:16.66666667%}.col-lg-3{flex:0 0 auto;width:25%}.col-lg-4{flex:0 0 auto;width:33.33333333%}.col-lg-5{flex:0 0 auto;width:41.66666667%}.col-lg-6{flex:0 0 auto;width:50%}.col-lg-7{flex:0 0 auto;width:58.33333333%}.col-lg-8{flex:0 0 auto;width:66.66666667%}.col-lg-9{flex:0 0 auto;width:75%}}@media (min-width:1200px){.col-xl-4{flex:0 0 auto;width:33.33333333%}}.order-1{order:1 !important}.order-2{order:2 !important}@media (min-width:992px){.order-lg-1{order:1 !important}.order-lg-2{order:2 !important}}.d-none{display:none !important}.d-flex{display:flex !important}.d-inline-flex{display:inline-flex !important}@media (min-width:768px){.d-md-flex{display:flex !important}}@media (min-width:992px){.d-lg-none{display:none !important}.d-lg-inline-flex{display:inline-flex !important}}.flex-column{flex-direction:column !important}.flex-wrap{flex-wrap:wrap !important}.justify-content-center{justify-content:center !important}.justify-content-between{justify-content:space-between !important}.align-items-center{align-items:center !important}.align-items-start{align-items:flex-start !important}.align-items-end{align-items:flex-end !important}@media (min-width:992px){.align-items-lg-start{align-items:flex-start !important}}.gap-1{gap:0.25rem !important}.gap-3{gap:1rem !important}.w-100{width:100% !important}.h-100{height:100% !important}.mb-0{margin-bottom:0 !important}.mb-1{margin-bottom:0.25rem !important}.mb-2{margin-bottom:0.5rem !important}.mb-3{margin-bottom:1rem !important}.mb-4{margin-bottom:1.5rem !important}.mb-5{margin-bottom:3rem !important}.mt-2{margin-top:0.5rem !important}.mt-3{margin-top:1rem !important}.mt-4{margin-top:1.5rem !important}.mt-5{margin-top:3rem !important}.mx-3{margin-left:1rem !important;margin-right:1rem !important}.mx-auto{margin-left:auto !important;margin-right:auto !important}.my-1{margin-top:0.25rem !important;margin-bottom:0.25rem !important}.my-4{margin-top:1.5rem !important;margin-bottom:1.5rem !important}.p-4{padding:1.5rem !important}.pt-4{padding-top:1.5rem !important}@media (min-width:768px){.p-md-5{padding:3rem !important}}.text-center{text-align:center !important}.text-decoration-none{text-decoration:none !important}.text-muted{color:var(--hl-text-muted) !important}.text-white{color:#fff !important}.lead{font-size:1.25rem;font-weight:300}.visually-hidden{position:absolute !important;width:1px !important;height:1px !important;padding:0 !important;margin:-1px !important;overflow:hidden !important;clip:rect(0,0,0,0) !important;white-space:nowrap !important;border:0 !important}.form-label{display:inline-block;margin-bottom:0.5rem;font-size:0.92rem;font-weight:600;color:var(--hl-text)}.form-control,.form-select{display:block;width:100%;padding:0.75rem 1rem;font-size:0.98rem;font-weight:400;line-height:1.5;color:var(--hl-text);background-color:var(--hl-surface);border:1.5px solid var(--hl-border);border-radius:var(--hl-radius-sm);transition:border-color var(--hl-transition),box-shadow var(--hl-transition)}.form-control:focus,.form-select:focus{border-color:var(--hl-accent-dark);outline:0;box-shadow:0 0 0 3px rgba(84,90,72,0.15)}.collapse:not(.show){display:none}.collapsing{height:0;overflow:hidden;transition:height 0.35s ease}
'@

# Replace the original minimal .row
$oldRow = ".row{display:flex;flex-wrap:wrap;margin-right:-0.75rem;margin-left:-0.75rem}"
if ($css.Contains($oldRow)) {
    $css = $css.Replace($oldRow, $gridSystem)
} else {
    $css = $css + "`n" + $gridSystem
}

[System.IO.File]::WriteAllText("assets\css\style.css", $css, [System.Text.Encoding]::UTF8)
Write-Host "Updated assets\css\style.css. Size: $((Get-Item assets\css\style.css).Length) bytes"
